#!/bin/bash
# Sets APPLE_ID and APPLE_APP_PASSWORD on OyadotAI/keel for notarisation.
#
# An app-specific password cannot be generated by a script: Apple issues it at
# appleid.apple.com > Sign-In and Security > App-Specific Passwords. This loads both values from,
# in order: the environment, the login keychain item `keel-notary` (saved here after a first run),
# or a macOS dialog, which works without a terminal. They are checked against Apple's notary
# service before anything is uploaded, so a typo fails here and not 15 minutes into a release.
set -euo pipefail
REPO=${REPO:-OyadotAI/keel}
TEAM=${APPLE_TEAM_ID:-68267DX5UC}
ITEM=keel-notary

ask() { # ask <prompt> <default> <hidden>
  local hidden=""; [ "$3" = hidden ] && hidden="with hidden answer"
  osascript -e "text returned of (display dialog \"$1\" default answer \"$2\" $hidden buttons {\"Cancel\", \"OK\"} default button \"OK\" with title \"Keel notarisation\")"
}

APPLE_ID=${APPLE_ID:-$(security find-generic-password -s "$ITEM" -g 2>&1 | sed -n 's/.*"acct"<blob>="\(.*\)"/\1/p' || true)}
if [ -z "${APPLE_APP_PASSWORD:-}" ] && [ -n "$APPLE_ID" ]; then
  APPLE_APP_PASSWORD=$(security find-generic-password -s "$ITEM" -a "$APPLE_ID" -w 2>/dev/null || true)
fi

if [ -z "$APPLE_ID" ]; then
  APPLE_ID=$(ask "Apple ID email of the account in team $TEAM:" "" visible)
fi
if [ -z "${APPLE_APP_PASSWORD:-}" ]; then
  open "https://account.apple.com/account/manage/section/security"
  APPLE_APP_PASSWORD=$(ask "Create an app-specific password named Keel notarisation in the page that just opened, then paste it here:" "" hidden)
fi

echo "Checking the credentials with Apple's notary service…"
if ! xcrun notarytool history --apple-id "$APPLE_ID" --password "$APPLE_APP_PASSWORD" --team-id "$TEAM" >/dev/null 2>&1; then
  echo "Apple rejected $APPLE_ID with that password for team $TEAM. Nothing was uploaded." >&2
  security delete-generic-password -s "$ITEM" -a "$APPLE_ID" >/dev/null 2>&1 || true
  exit 1
fi

security add-generic-password -U -s "$ITEM" -a "$APPLE_ID" -w "$APPLE_APP_PASSWORD"
printf %s "$APPLE_ID" | gh secret set APPLE_ID -R "$REPO"
printf %s "$APPLE_APP_PASSWORD" | gh secret set APPLE_APP_PASSWORD -R "$REPO"
printf %s "$TEAM" | gh secret set APPLE_TEAM_ID -R "$REPO"
echo "Set APPLE_ID, APPLE_APP_PASSWORD and APPLE_TEAM_ID on $REPO; saved to the login keychain as $ITEM."
